def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Horizontal bars are the dense rows; join gaps between matching colors.
    bar_rows = [r for r in range(h) if sum(v != 0 for v in grid[r]) >= 4]
    if not bar_rows:
        return out
    last_bar = max(bar_rows)

    for r in bar_rows:
        occupied = [c for c in range(w) if grid[r][c] != 0]
        for a, b in zip(occupied, occupied[1:]):
            if grid[r][a] == grid[r][b]:
                for c in range(a + 1, b):
                    out[r][c] = grid[r][a]

    marker_cols = [
        c for c in range(w)
        if any(grid[r][c] != 0 for r in range(last_bar + 1, h))
    ]

    for c in marker_cols:
        events = [(r, out[r][c]) for r in bar_rows if out[r][c] != 0]

        prev = -1
        color = None
        for r, new_color in events:
            color = new_color
            for rr in range(prev + 1, r + 1):
                out[rr][c] = color
            prev = r

        if color is not None:
            for rr in range(prev + 1, last_bar + 1):
                out[rr][c] = color

        marker_color = next(
            (grid[r][c] for r in range(last_bar + 1, h) if grid[r][c] != 0),
            None
        )
        if marker_color is not None:
            for rr in range(last_bar + 1, h):
                out[rr][c] = marker_color

    return out
